(() => {const initIdleToggle = () => {const idleToggle = document.querySelector('[data-oliforge-idle-toggle]');const idleRow = document.querySelector('[data-oliforge-idle-row]');if (!idleToggle || !idleRow) return;const sync = () => {idleRow.hidden = !idleToggle.checked;};idleToggle.addEventListener('change', sync);sync();};const initConfirmLinks = () => {document.querySelectorAll('[data-oliforge-confirm]').forEach((el) => {el.addEventListener('click', (event) => {if (!window.confirm(el.dataset.oliforgeConfirm)) {event.preventDefault();}});});};const initAutoDismissNotice = () => {const notice = document.querySelector('.oliforge-auto-dismiss');const url = new URL(window.location.href);if (url.searchParams.has('oliforge_synced')) {url.searchParams.delete('oliforge_synced');window.history.replaceState({}, '', url.toString());}if (!notice) return;window.setTimeout(() => {notice.style.transition = 'opacity .2s ease, transform .2s ease';notice.style.opacity = '0';notice.style.transform = 'translateY(-8px)';window.setTimeout(() => notice.remove(), 200);}, 4000);};initIdleToggle();initConfirmLinks();initAutoDismissNotice();})();